#!/bin/bash
# Starts/stops a throwaway, TLS-only Redis container for integration testing.
# Requires certs generated by gen-test-tls-certs.sh to already exist.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/.." && pwd)"
CERTS_DIR="$REPO_ROOT/testdata/tls/certs"

CONTAINER_NAME="pubsub-bench-redis-tls"
REDIS_IMAGE="${REDIS_IMAGE:-redis:8}"
TLS_PORT="${PUBSUB_BENCH_TLS_PORT:-16390}"

start() {
    if [[ ! -f "$CERTS_DIR/ca.crt" ]]; then
        echo "[redis-tls-docker] certs not found in $CERTS_DIR, run gen-test-tls-certs.sh first" >&2
        exit 1
    fi

    docker rm -f "$CONTAINER_NAME" >/dev/null 2>&1 || true

    echo "[redis-tls-docker] starting $CONTAINER_NAME ($REDIS_IMAGE) on TLS port $TLS_PORT"
    docker run -d --name "$CONTAINER_NAME" \
        -p "${TLS_PORT}:${TLS_PORT}" \
        -v "$CERTS_DIR:/tls:ro" \
        "$REDIS_IMAGE" \
        redis-server \
        --port 0 \
        --tls-port "$TLS_PORT" \
        --tls-cert-file /tls/redis.crt \
        --tls-key-file /tls/redis.key \
        --tls-ca-cert-file /tls/ca.crt \
        >/dev/null

    echo "[redis-tls-docker] waiting for Redis to become ready..."
    for _ in $(seq 1 30); do
        if docker exec "$CONTAINER_NAME" redis-cli \
            --tls --cert /tls/client.crt --key /tls/client.key --cacert /tls/ca.crt \
            -p "$TLS_PORT" ping 2>/dev/null | grep -q PONG; then
            echo "[redis-tls-docker] ready"
            return 0
        fi
        sleep 1
    done

    echo "[redis-tls-docker] Redis did not become ready in time" >&2
    docker logs "$CONTAINER_NAME" >&2 || true
    exit 1
}

stop() {
    echo "[redis-tls-docker] stopping $CONTAINER_NAME"
    docker rm -f "$CONTAINER_NAME" >/dev/null 2>&1 || true
}

case "${1:-}" in
    start) start ;;
    stop) stop ;;
    *)
        echo "usage: $0 {start|stop}" >&2
        exit 1
        ;;
esac
